<!-- about-team -->
<section class="about-team section-bg">
    <div class="container">
        <div class="about-team__content">
            <div class="head-content fade-in-up">
                <h2 class="title title--h2">Соединяем архитектурную эстетику <br>и&nbsp;инженерную честность</h2>
                <div class="subtitle"><p>За&nbsp;плечами команды&nbsp;&mdash; частные резиденции от&nbsp;300 до&nbsp;1&nbsp;500&nbsp;м&sup2; и&nbsp;клубные поселки камерного формата. <br>Мы&nbsp;умеем превращать сложные замыслы в&nbsp;дома.</p></div>
            </div>
        </div>
    </div>
    <div class="about-team__bg">
        <div class="about-team__bg-cover fade-in">
            <picture> 
                <source srcset="img/default.png" data-srcset="img/team/bg-xs.webp 1x, img/team/bg-xs@2x.webp 2x" media="(max-width:479px)" type="image/webp">
                <source srcset="img/default.png" data-srcset="img/team/bg-xs.jpg 1x, img/team/bg-xs@2x.jpg 2x" media="(max-width:479px)" type="image/jpeg">

                <source srcset="img/default.png" data-srcset="img/team/bg.webp 1x, img/team/bg@2x.webp 2x" type="image/webp">
                <source srcset="img/default.png" data-srcset="img/team/bg.jpg 1x, img/team/bg@2x.jpg 2x" type="image/jpeg">
                <img class="lazyload" src="img/default.png" data-srcset="img/team/bg.jpg 1x, img/team/bg@2x.jpg 2x" alt="img">
            </picture>
        </div>
    </div>
</section>